package com.interview.fraud.platform;
import java.time.Instant; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class AuditService { private final JdbcTemplate jdbc; public AuditService(JdbcTemplate jdbc){this.jdbc=jdbc;} public void log(String actor,String action,String type,String entity,String details){jdbc.update("INSERT INTO audit_logs(id,correlation_id,actor,action,entity_type,entity_id,details_masked,created_at) VALUES(?,?,?,?,?,?,?,?)",UUID.randomUUID(),Optional.ofNullable(org.slf4j.MDC.get("correlationId")).orElse("local"),actor,action,type,entity,mask(details),Instant.now());} public List<Map<String,Object>> forEntity(String type,String id){return jdbc.queryForList("SELECT actor,action,details_masked,created_at FROM audit_logs WHERE entity_type=? AND entity_id=? ORDER BY created_at",type,id);} private String mask(String v){return v==null?"":v.replaceAll("(?i)(email|phone|cardNumber)\\s*[:=]\\s*[^, }]+","$1=***");}}
